`,r.jsx(o.p,{children:"Me fekk tilbakemeldingar om at teksten på knappane for filtrering av programmet kunne vere meir beskrivande, og at det kunne hjelpe brukarane med å forstå kva dei ulike filtreringsalternativa innebar."}),`
